// === ESTRUCTURA DEL PATRÓN COMMAND ===

// 1. Interfaz Command (el contrato)
interface Command {
  execute(): void;
  undo(): void;
}

// 2. Receptor (el que hace el trabajo real)
class TextDocument {
  private content: string = '';

  insert(text: string) { this.content += text; }
  delete(length: number) { this.content = this.content.slice(0, -length); }
  getContent(): string { return this.content; }
}

// 3. Comandos Concretos
class InsertCommand implements Command {
  constructor(private doc: TextDocument, private text: string) {}
  execute() { this.doc.insert(this.text); }
  undo() { this.doc.delete(this.text.length); }
}

class DeleteCommand implements Command {
  constructor(private doc: TextDocument, private length: number) {}
  execute() { this.doc.delete(this.length); }
  undo() { /* restaurar texto borrado */ }
}

// 4. Invocador (almacena historial)
class Editor {
  private history: Command[] = [];

  execute(cmd: Command) {
    cmd.execute();
    this.history.push(cmd);
  }

  undo() {
    const cmd = this.history.pop();
    cmd?.undo();
  }
}

// Uso:
const doc = new TextDocument();
const editor = new Editor();
editor.execute(new InsertCommand(doc, 'Hola'));
editor.execute(new InsertCommand(doc, ' Mundo'));
console.log(doc.getContent()); // → 'Hola Mundo'
editor.undo();
console.log(doc.getContent()); // → 'Hola'

