// 1. Interfaz Command con undo
interface Command {
  execute(): void;
  undo(): void;
}

// 2. Comandos concretos encapsulan la lógica
class InsertCommand implements Command {
  constructor(private doc: TextDocument, private text: string) {}
  execute() { this.doc.insert(this.text); }
  undo() { this.doc.delete(this.text.length); }
}

// 3. Invocador con historial
class Editor {
  private history: Command[] = [];
  execute(cmd: Command) { cmd.execute(); this.history.push(cmd); }
  undo() { this.history.pop()?.undo(); }
}

